<template>
  <div class="sg-client-page sg3-utility-page"><PublicNavbar /><main class="sg3-container sg3-profile-main"><div class="sg3-page-head"><div><div class="sg3-breadcrumbs"><router-link to="/profile">Tài khoản</router-link><span>/</span><strong>Thông báo</strong></div><p class="sg3-kicker">Trung tâm cập nhật</p><h1>Thông báo</h1><p>Cập nhật về booking, thanh toán, hoàn tiền và tài khoản của bạn.</p></div><button class="sg3-button sg3-button--secondary" type="button" :disabled="!unreadCount || markingAll" @click="markAllRead"><AppIcon name="check" :size="16" />Đánh dấu đã đọc</button></div><ClientAccountNav /><section v-if="loading" class="sg3-empty"><div><strong>Đang tải thông báo</strong><p>Đang kiểm tra cập nhật mới nhất.</p></div></section><section v-else-if="error" class="sg3-error"><div><strong>Không tải được thông báo</strong><p>{{ error }}</p><button class="sg3-button sg3-button--primary" type="button" @click="load">Thử lại</button></div></section><section v-else class="sg3-card sg3-notification-card"><header><div><strong>{{ unreadCount }}</strong><span> thông báo chưa đọc</span></div><button class="sg3-button sg3-button--quiet" type="button" @click="load">Làm mới</button></header><div v-if="!notifications.length" class="sg3-empty sg3-empty--inline"><div><strong>Bạn chưa có thông báo nào</strong><p>Những cập nhật quan trọng sẽ được lưu tại đây.</p></div></div><button v-for="notification in notifications" :key="notification.id" type="button" class="sg3-notification-row" :class="{ 'is-unread': !notification.is_read }" @click="openNotification(notification)"><span class="sg3-notification-icon"><AppIcon name="bell" :size="17" /></span><span><strong>{{ notification.title || "Thông báo SportGo" }}</strong><span>{{ notification.body }}</span><small>{{ formatDate(notification.created_at) }}</small></span><i v-if="!notification.is_read"></i><AppIcon name="chevronRight" :size="16" /></button></section></main></div>
</template>
<script>
import AppIcon from "../../components/AppIcon.vue"; import ClientAccountNav from "../../components/ClientAccountNav.vue"; import PublicNavbar from "../../components/PublicNavbar.vue"; import { notificationService } from "../../services/notification.service.js";
export default { name:"ClientNotifications", components:{AppIcon,ClientAccountNav,PublicNavbar}, data(){return{notifications:[],unreadCount:0,loading:true,error:"",markingAll:false};}, mounted(){this.load();}, methods:{async load(){this.loading=true;this.error="";try{const response=await notificationService.getNotifications();this.notifications=response.data||[];this.unreadCount=Number(response.unread_count||0);}catch(error){this.error=error.message||"Vui lòng thử lại.";}finally{this.loading=false;}},async markAllRead(){this.markingAll=true;try{await notificationService.markAllAsRead();this.notifications=this.notifications.map((item)=>({...item,is_read:true}));this.unreadCount=0;}catch(error){this.error=error.message||"Không thể cập nhật thông báo.";}finally{this.markingAll=false;}},async openNotification(notification){if(!notification.is_read){try{await notificationService.markAsRead(notification.id);notification.is_read=true;this.unreadCount=Math.max(0,this.unreadCount-1);}catch{}}const type=String(notification.reference_type||"").toLowerCase();if(type.includes("booking")&&notification.reference_id)this.$router.push({name:"booking-detail",params:{id:notification.reference_id}});else if(type.includes("refund")&&notification.reference_id)this.$router.push({name:"client-refund-detail",params:{id:notification.reference_id}});else if(type.includes("complaint")&&notification.reference_id)this.$router.push({name:"client-complaint-detail",params:{id:notification.reference_id}});},formatDate(value){return value?new Date(value).toLocaleString("vi-VN"):"";}}};
</script>
